	{{"turnin", 79980, at = {1442, 39.62, 49.86}, who = "Mound of Dirt"}, {"accept", 79974, at = {1442, 39.62, 49.86}, who = "Mound of Dirt"}, note = "Walk north through the camp and drop carefully down the steep slope to the Mound of Dirt on the ledge below. A missed jump only slides you down: hug the cliff and walk back up.", title = "A hundred paces north"},
	{{"turnin", 79974, at = {1432, 49.35, 12.9}, who = "Carved Figurine"}, {"accept", 79975, at = {1432, 49.35, 12.9}, who = "Carved Figurine"}, note = "The figurine is on a ledge just below the top of the Stonewrought Dam, on its north face. Step off slowly; walking backwards keeps you from overshooting the ledge.", title = "The dam in Loch Modan"},
	{{"goto", 1424, 87.5, 47.7, "Fallen cart"}, note = "At the gate in Thoradin's Wall between Arathi and Hillsbrad, turn north and follow the wall on the Hillsbrad side to a fallen cart leaning against it. Jump up the cart and its ladder onto the wall, then over the rocks to the hidden camp. Some characters cannot fit under the cargo netting at the camp; another race or a smaller form gets through.", title = "Thoradin's Wall"},
	{{"turnin", 79975, at = {1417, 22.46, 24.21}, who = "Messenger Bag"}, {"accept", 79976, at = {1417, 22.46, 24.21}, who = "Messenger Bag"}, {"turnin", 79976, at = {1417, 22.45, 24.21}, who = "Hastily Rolled-Up Satchel"}, title = "The hidden camp"},
} })

Pathwise.RegisterRoute({category = "Miscellaneous", id = "forever/miscellaneous/library-books", levels = {20, 50}, map = 1453, title = "Library Books", steps = {
	{{"have", 203755, 1, at = {1429, 65.4, 70.1}, name = "Archmage Theocritus' Research Journal"}, note = "Halfway up the Tower of Azora, east of Goldshire. Nothing hostile inside.", only = {factions = {"Alliance"}}, title = "Elwynn Forest"},
	{{"have", 209845, 1, at = {1436, 45.4, 70.4}, name = "Bewitchments and Glamours"}, {"have", 208860, 1, at = {1436, 52.7, 53.8}, hint = "Rumi of Gnomeregan", name = "Rumi of Gnomeregan: The Collected Works", only = {factions = {"Alliance"}}}, note = "Two books: one in a house at Moonbrook, one at Sentinel Hill (Alliance only).", title = "Westfall"},
	{{"have", 209849, 1, at = {1431, 16.7, 28.4}, name = "Crimes Against Anatomy"}, note = "The spellbook lies in the Dawning Wood Catacombs, the crypt in north-western Duskwood. Undead fill it; a corpse run works if you are low.", title = "Duskwood"},
	{{"have", 213165, 1, at = {1434, 41.5, 50.9}, name = "Basilisks: Should Petrification be Feared?"}, note = "On a bench beside the Crystalvein Mine entrance, in the middle of the zone.", title = "Stranglethorn Vale"},
	{{"have", 220345, 1, at = {1435, 70, 51}, name = "Sanguine Sorcery"}, note = "On the top walkway of the Temple of Atal'Hakkar, outside the dungeon.", title = "Swamp of Sorrows"},
	{{"have", 220353, 1, at = {1419, 55.4, 32.2}, name = "Conjurer's Codex"}, title = "Blasted Lands"},
	{{"have", 220349, 1, at = {1428, 28.96, 28.93}, name = "Stonewrought Design"}, note = "Inside Blackrock Mountain, not in a dungeon: the book lies on the altar in Franclorn Forgewright's tomb, near Lothos Riftwaker. The waypoint marks the mountain.", title = "Blackrock Mountain"},
