	{{"have", 215820, 1, at = {1418, 56.7, 39.9}, name = "Mummies: A Guide to the Unsavory Undead"}, note = "Inside a crypt near the middle of the zone, reached from the path to its south.", title = "Badlands"},
	{{"have", 209850, 1, at = {1432, 77.4, 14}, name = "Runes of the Sorcerer-Kings"}, note = "Scrolls in the Mo'grosh ogre cave in the north-east. The ogres in the cave are level 18-19 elites: grouping up is advised. (Rumi of Gnomeregan also lies in Thelsamar, if you missed it at Sentinel Hill.)", only = {factions = {"Alliance"}}, title = "Loch Modan"},
	{{"have", 203754, 1, at = {1455, 76, 10.4}, name = "Archmage Antonidas: The Unabridged Autobiography"}, only = {factions = {"Alliance"}}, title = "Ironforge"},
	{{"have", 209848, 1, at = {1437, 33.6, 47.9}, name = "Goaz Scrolls"}, title = "Wetlands"},
	{{"have", 215816, 1, at = {1417, 73.6, 65.2}, name = "A Web of Lies: Debunking Myths and Legends"}, note = "Beside a tent entrance in the troll village in south-eastern Arathi.", title = "Arathi Highlands"},
	{{"have", 220350, 1, at = {1425, 36, 72.8}, name = "Venomous Journeys"}, title = "The Hinterlands"},
	{{"have", 215815, 1, at = {1416, 48.4, 57.6}, name = "Defensive Magics 101"}, title = "Alterac Mountains"},
	{{"have", 209844, 1, at = {1421, 63.5, 63.2}, hint = "The Dalaran Digest", name = "The Dalaran Digest, Vol. 23"}, title = "Silverpine Forest"},
	{{"have", 208185, 1, at = {1420, 59.4, 52.3}, name = "The Apothecary's Metaphysical Primer"}, note = "On a shelf in Brill's apothecary.", only = {factions = {"Horde"}}, title = "Tirisfal Glades"},
	{{"have", 209843, 1, at = {1439, 59.6, 22.2}, hint = "Nar'thalas Almanac", name = "Nar'thalas Almanac, Vol. 74"}, note = "Down the stairs at the Ruins of Mathystra in northern Darkshore.", title = "Darkshore"},
	{{"have", 220348, 1, at = {1447, 20.7, 62}, name = "Everyday Etiquette"}, note = "On a crate in the Haldarr Encampment, in the far west of Azshara.", title = "Azshara"},
	{{"have", 207972, 1, at = {1454, 38.7, 78.4}, name = "The Lessons of Ta'zo"}, note = "The Mural of Ta'zo is the stone tablet leaning against the wall in the Valley of Spirits, on the way to the mage trainers. Use it to take the book.", only = {factions = {"Horde"}}, title = "Orgrimmar"},
	{{"have", 209846, 1, at = {1413, 49.3, 32.9}, name = "Secrets of the Dreamers"}, {"have", 209847, 1, at = {1413, 56.3, 8.8}, name = "Arcanic Systems Manual"}, {"have", 208800, 1, at = {1413, 62.7, 36.3}, name = "Baxtan: On Destructive Magics"}, note = "Three books: scrolls outside the Wailing Caverns entrance, the manual in the control room at the top of the oil rig at the Sludge Fen, and the Goblin Tome beside Gazlowe in Ratchet.", title = "The Barrens"},
	{{"have", 209851, 1, at = {1442, 74.4, 85.7}, name = "Fury of the Land"}, note = "On a barrel in a tent at Grimtotem Post, in the far south-east of the zone.", title = "Stonetalon Mountains"},
