Pathwise.RegisterRoute({category = "Reputation", id = "forever/reputation/alterac-valley", levels = {51, 60}, map = 1459, title = "Alterac Valley Reputation", steps = {
	{{"accept", 7223, at = {1459, 43.48, 15.5}, optional = true, who = "Murgot Deepforge"}, {"turnin", 7223, at = {1459, 43.48, 15.5}, optional = true, who = "Murgot Deepforge"}, {"goto", 1459, 43.12, 17.62, "Talk to Stormpike Quartermaster", optional = true}, {"note", "Stormpike Guard: reach Friendly"}, note = "The Stormpike Guard holds Dun Baldar in the north of Alterac Valley. Destroying towers, taking graveyards and mines, and killing captains and generals all pay reputation to the whole team. Loot Armor Scraps from fallen enemies for Murgot Deepforge. Forever's Legacy Diplomat perk increases reputation gains.", only = {factions = {"Alliance"}}, title = "Stormpike Guard to Friendly"},
	{{"goto", 1459, 43.48, 15.5, "Talk to Murgot Deepforge", optional = true}, {"goto", 1459, 43.9, 12.61, "Talk to Arch Druid Renferal", optional = true}, {"note", "Stormpike Guard: reach Honored"}, note = "Keep winning Alterac Valley. More Armor Scraps (Murgot Deepforge), Storm Crystals for Arch Druid Renferal (they summon Ivus the Forest Lord) and Frostwolf Hides for the Stormpike Ram Rider Commander all repeat.", only = {factions = {"Alliance"}}, title = "Stormpike Guard to Honored"},
	{{"note", "Stormpike Guard: reach Revered"}, note = "Full games that kill Drek'Thar after the towers fall pay the most.", only = {factions = {"Alliance"}}, title = "Stormpike Guard to Revered"},
	{{"note", "Stormpike Guard: reach Exalted"}, note = "Exalted with the Stormpike Guard earns a Legacy Point.", only = {factions = {"Alliance"}}, title = "Stormpike Guard to Exalted"},
	{{"accept", 7224, at = {1459, 49.5, 82.72}, optional = true, who = "Smith Regzar"}, {"turnin", 7224, at = {1459, 49.5, 82.72}, optional = true, who = "Smith Regzar"}, {"goto", 1459, 46.62, 84.22, "Talk to Frostwolf Quartermaster", optional = true}, {"note", "Frostwolf Clan: reach Friendly"}, note = "The Frostwolf Clan holds Frostwolf Keep in the south of Alterac Valley. Destroying towers, taking graveyards and mines, and killing captains and generals all pay reputation to the whole team. Loot Armor Scraps from fallen enemies for Smith Regzar. Forever's Legacy Diplomat perk increases reputation gains.", only = {factions = {"Horde"}}, title = "Frostwolf Clan to Friendly"},
	{{"goto", 1459, 49.5, 82.72, "Talk to Smith Regzar", optional = true}, {"goto", 1459, 50.12, 85.13, "Talk to Primalist Thurloga", optional = true}, {"note", "Frostwolf Clan: reach Honored"}, note = "Keep winning Alterac Valley. More Booty! (Smith Regzar), Stormpike Soldier's Blood for Primalist Thurloga (it summons Lokholar the Ice Lord) and Alterac Ram Hides for the Frostwolf Wolf Rider Commander all repeat.", only = {factions = {"Horde"}}, title = "Frostwolf Clan to Honored"},
	{{"note", "Frostwolf Clan: reach Revered"}, note = "Full games that kill Vanndar Stormpike after the towers fall pay the most.", only = {factions = {"Horde"}}, title = "Frostwolf Clan to Revered"},
	{{"note", "Frostwolf Clan: reach Exalted"}, note = "Exalted with the Frostwolf Clan earns a Legacy Point.", only = {factions = {"Horde"}}, title = "Frostwolf Clan to Exalted"},
} })

Pathwise.RegisterRoute({category = "Reputation", id = "forever/reputation/arathi-basin", levels = {20, 60}, map = 1417, title = "Arathi Basin Reputation", steps = {
	{{"goto", 1417, 45.82, 45.46, "Talk to Field Marshal Oslight", optional = true}, {"note", "Field Marshal Oslight's The Battle for Arathi Basin! (assault every base) and Control Four Bases / Control Five Bases are one-time quests; Sergeant Maclear beside him takes Arathi Resource Crates."}, {"note", "The League of Arathor: reach Friendly"}, note = "The League of Arathor fights for Arathi Basin from Refuge Pointe. Their reputation comes from the battleground: the resources your team gathers pay it to everyone, so holding more bases for longer pays more. Queue at any battlemaster. Forever's Legacy Diplomat perk increases reputation gains.", only = {factions = {"Alliance"}}, title = "League of Arathor to Friendly"},
	{{"goto", 1417, 45.97, 45.21, "Talk to Samuel Hawke", optional = true}, {"note", "The League of Arathor: reach Honored"}, note = "Keep playing Arathi Basin. On Call to Arms: Arathi Basin weekends the Alliance Brigadier General in the capitals takes three Arathi Basin Marks of Honor for extra reputation.", only = {factions = {"Alliance"}}, title = "League of Arathor to Honored"},
	{{"note", "The League of Arathor: reach Revered"}, note = "Keep playing Arathi Basin; wins with many bases held pay the most.", only = {factions = {"Alliance"}}, title = "League of Arathor to Revered"},
	{{"note", "The League of Arathor: reach Exalted"}, note = "Exalted with the League of Arathor earns a Legacy Point.", only = {factions = {"Alliance"}}, title = "League of Arathor to Exalted"},
	{{"goto", 1417, 73.25, 29.73, "Talk to Deathmaster Dwire", optional = true}, {"note", "Deathmaster Dwire's The Battle for Arathi Basin! (assault every base) and Take Four Bases / Take Five Bases are one-time quests; Deathstalker Mortis beside him takes Arathi Resource Crates."}, {"note", "The Defilers: reach Friendly"}, note = "The Defilers fight for Arathi Basin from Hammerfall. Their reputation comes from the battleground: the resources your team gathers pay it to everyone, so holding more bases for longer pays more. Queue at any battlemaster. Forever's Legacy Diplomat perk increases reputation gains.", only = {factions = {"Horde"}}, title = "The Defilers to Friendly"},
	{{"goto", 1417, 73.37, 29.67, "Talk to Rutherford Twing", optional = true}, {"note", "The Defilers: reach Honored"}, note = "Keep playing Arathi Basin. On Call to Arms: Arathi Basin weekends the Horde Warbringer in the capitals takes three Arathi Basin Marks of Honor for extra reputation.", only = {factions = {"Horde"}}, title = "The Defilers to Honored"},
	{{"note", "The Defilers: reach Revered"}, note = "Keep playing Arathi Basin; wins with many bases held pay the most.", only = {factions = {"Horde"}}, title = "The Defilers to Revered"},
	{{"note", "The Defilers: reach Exalted"}, note = "Exalted with The Defilers earns a Legacy Point.", only = {factions = {"Horde"}}, title = "The Defilers to Exalted"},
