Pathwise.RegisterRoute({category = "Reputation", id = "forever/reputation/argent-dawn", levels = {50, 60}, map = 1422, title = "Argent Dawn Reputation", steps = {
	{{"accept", 5401, at = {1422, 42.97, 83.55}, who = "Argent Officer Pureheart"}, {"turnin", 5401, at = {1422, 42.97, 83.55}, who = "Argent Officer Pureheart"}, note = "The Argent Dawn starts out Neutral. Take the Commission from Argent Officer Pureheart at Chillwind Camp and wear it: in Classic, Scourgestones only drop while the Argent Dawn Commission trinket is equipped. Forever's Legacy Diplomat perk increases reputation gains.", only = {factions = {"Alliance"}}, title = "Argent Dawn Commission (Alliance)"},
	{{"accept", 5405, at = {1420, 83.19, 68.45}, who = "Argent Officer Garush"}, {"turnin", 5405, at = {1420, 83.19, 68.45}, who = "Argent Officer Garush"}, note = "The Argent Dawn starts out Neutral. Take the Commission from Argent Officer Garush at The Bulwark and wear it: in Classic, Scourgestones only drop while the Argent Dawn Commission trinket is equipped. Forever's Legacy Diplomat perk increases reputation gains.", only = {factions = {"Horde"}}, title = "Argent Dawn Commission (Horde)"},
	{{"have", 12840, 20, at = {1422, 41.8, 70.4}, name = "Minion's Scourgestone", optional = true}, {"goto", 1422, 42.97, 83.55, "Talk to Argent Officer Pureheart", only = {factions = {"Alliance"}}, optional = true}, {"goto", 1422, 26.6, 55.5, "Talk to Argent Officer Garush", only = {factions = {"Horde"}}, optional = true}, {"note", "Argent Dawn: reach Friendly"}, note = "Ghouls and skeletons all over Western Plaguelands drop Minion's Scourgestones about half the time; this cluster is dense. Hand them in 20 at a time to any Argent Officer (Pureheart at Chillwind Camp, Garush at The Bulwark, Duke Nicholas Zverenhoff at Light's Hope Chapel). Each turn-in also pays an Argent Dawn Valor Token for the Argent quartermasters.", title = "Minion's Scourgestones to Friendly"},
	{{"have", 12841, 10, at = {1423, 34.34, 42.41}, name = "Invader's Scourgestone", optional = true}, {"goto", 1423, 71.63, 50.09, "Talk to Duke Nicholas Zverenhoff", optional = true}, {"note", "Argent Dawn: reach Honored"}, note = "Dark Adepts and Shadowmages (level 58-60) drop Invader's Scourgestones here, along with Minion's stones and Runecloth. Hand Invader's in 10 at a time and Minion's 20 at a time to Duke Nicholas Zverenhoff at Light's Hope Chapel. In Classic both stop giving reputation at Honored.", title = "Invader's Scourgestones to Honored"},
	{{"note", "Run Stratholme (both wings) and Scholomance, killing every Scourge you pass."}, {"goto", 1423, 71.63, 50.09, "Talk to Duke Nicholas Zverenhoff", optional = true}, {"note", "Argent Dawn: reach Revered"}, note = "From Honored on, Corruptor's Scourgestones (one per turn-in) and Scourge kills in Stratholme and Scholomance carry the reputation. Corruptor's stones drop from the Scourge bosses there (Darkmaster Gandling, Marduk Blackpool, Vectus) and from Araj the Summoner and Putridius in Western Plaguelands. Many dungeon runs pay off faster than any open-world farm.", title = "Corruptor's Scourgestones and dungeons to Revered"},
	{{"goto", 1423, 71.63, 50.09, "Talk to Duke Nicholas Zverenhoff", optional = true}, {"note", "Argent Dawn: reach Exalted"}, note = "Keep running Stratholme and Scholomance and turning in every Corruptor's Scourgestone at Light's Hope Chapel until Exalted.", title = "Argent Dawn to Exalted"},
} })

Pathwise.RegisterRoute({category = "Reputation", id = "forever/reputation/cenarion-circle", levels = {57, 60}, map = 1451, title = "Cenarion Circle Reputation", steps = {
	{{"accept", 8318, at = {1451, 48.57, 37.78}, who = "Bor Wildmane"}, {"accept", 8320, at = {1451, 48.62, 37.87}, optional = true, who = "Huum Wildmane"}, note = "Cenarion Hold is the walled town in north-central Silithus. Bor and Huum Wildmane stand together inside. The Cenarion Circle starts out Neutral. Forever's Legacy Diplomat perk increases reputation gains.", title = "Cenarion Hold"},
	{{"complete", 8320, at = {1451, 26.2, 33.9}, optional = true}, {"complete", 8318, at = {1451, 26.3, 32.9}}, note = "Twilight's Hammer cultists hold the camps in western Silithus. Twilight Geolords and Stonecallers mix here; any cultist can drop an Encrypted Twilight Text. Every cultist kill also counts toward the Cenarion Circle. The Geolords count for Twilight Geolords only if you are 60 and took it.", title = "Twilight Base Camp"},
	{{"turnin", 8318, at = {1451, 48.57, 37.78}, who = "Bor Wildmane"}, {"turnin", 8320, at = {1451, 48.62, 37.87}, optional = true, who = "Huum Wildmane"}, title = "Back to Cenarion Hold"},
	{{"have", 20404, 10, at = {1451, 26.3, 32.9}, name = "Encrypted Twilight Text", optional = true}, {"goto", 1451, 48.57, 37.78, "Talk to Bor Wildmane", optional = true}, {"note", "Cenarion Circle: reach Friendly"}, note = "Encrypted Twilight Texts repeats: Bor Wildmane takes more texts again and again. The cultist camps are the place to farm them.", title = "Encrypted Twilight Texts to Friendly"},
	{{"have", 20404, 10, at = {1451, 26.3, 32.9}, name = "Encrypted Twilight Text", optional = true}, {"goto", 1451, 48.57, 37.78, "Talk to Bor Wildmane", optional = true}, {"note", "Cenarion Circle: reach Honored"}, note = "Keep farming the Twilight camps. Wearing the Twilight Trappings (the Twilight cultist set plus a Medallion of Station, from Aurel Goldleaf's Medallion of Station quest) lets you summon Abyssal Templars at the Wind Stones; their Abyssal Crests go to Bor Wildmane.", title = "Cenarion Circle to Honored"},
	{{"note", "Abyssal Crests, Abyssal Signets and Abyssal Scepters are repeatable at Bor Wildmane once their opening quests are done."}, {"note", "Cenarion Circle: reach Revered"}, note = "From here on, the Ruins of Ahn'Qiraj raid and the Abyssal Council turn-ins (crests, signets, scepters) carry most of the reputation.", title = "Cenarion Circle to Revered"},
	{{"note", "Cenarion Circle: reach Exalted"}, note = "Keep running the Ruins of Ahn'Qiraj and turning in Abyssal Council insignia until Exalted.", title = "Cenarion Circle to Exalted"},
} })

Pathwise.RegisterRoute({category = "Reputation", faction = "Horde", id = "forever/reputation/darkspear-trolls", levels = {12, 60}, map = 1454, title = "Darkspear Trolls Reputation", steps = {
	{{"level", 12}, {"accept", 7833, at = {1454, 37.7, 87.9}, who = "Vehena"}, note = "Vehena takes cloth for Darkspear Trolls in the Valley of Spirits, Orgrimmar. The first donations of Wool, Silk, Mageweave and Runecloth (60 cloth each) are done once and give the most reputation per cloth; after them, Additional Runecloth repeats until Exalted. Exalted with another race's city lets you buy that race's mounts. Forever's Legacy Diplomat perk increases reputation gains.", title = "Vehena: A Donation of Wool"},
	{{"complete", 7833, at = {1413, 61, 4.2}}, note = "Venture Co. Enforcers at the Boulder Lode Mine (level 16-17) drop it here. The Auction House works too.", title = "Wool Cloth"},
	{{"turnin", 7833, at = {1454, 37.7, 87.9}, who = "Vehena"}, {"level", 26}, {"accept", 7834, at = {1454, 37.7, 87.9}, who = "Vehena"}, title = "Vehena: A Donation of Silk"},
	{{"complete", 7834, at = {1443, 72.4, 47.1}}, note = "Kolkar centaur (level 30-33) drop it here. The Auction House works too.", title = "Silk Cloth"},
	{{"turnin", 7834, at = {1454, 37.7, 87.9}, who = "Vehena"}, {"level", 40}, {"accept", 7835, at = {1454, 37.7, 87.9}, who = "Vehena"}, title = "Vehena: A Donation of Mageweave"},
	{{"complete", 7835, at = {1446, 40.1, 54.4}}, note = "Dunemaul ogres (level 45-48) drop it here. The Auction House works too.", title = "Mageweave Cloth"},
	{{"turnin", 7835, at = {1454, 37.7, 87.9}, who = "Vehena"}, {"level", 50}, {"accept", 7836, at = {1454, 37.7, 87.9}, who = "Vehena"}, title = "Vehena: A Donation of Runecloth"},
	{{"complete", 7836, at = {1423, 34.34, 42.41}}, note = "Dark Adepts and Shadowmages (level 58-60) drop it here; every Scourge kill here also counts toward the Argent Dawn (see that guide). The Auction House works too.", title = "Runecloth"},
	{{"turnin", 7836, at = {1454, 37.7, 87.9}, who = "Vehena"}, title = "Vehena: Runecloth delivered"},
	{{"have", 14047, 20, at = {1423, 34.34, 42.41}, name = "Runecloth", optional = true}, {"turnin", 7837, at = {1454, 37.7, 87.9}, optional = true, who = "Vehena"}, {"note", "Darkspear Trolls: reach Honored"}, note = "Additional Runecloth takes 20 Runecloth per turn-in and repeats as often as you like. Bring Runecloth in multiples of 20 and hand them all in at once, one turn-in after another. Runecloth: Dark Adepts and Shadowmages (level 58-60) in Eastern Plaguelands, or the Auction House.", title = "Additional Runecloth to Honored"},
	{{"have", 14047, 20, at = {1423, 34.34, 42.41}, name = "Runecloth", optional = true}, {"turnin", 7837, at = {1454, 37.7, 87.9}, optional = true, who = "Vehena"}, {"note", "Darkspear Trolls: reach Revered"}, note = "Keep handing in Additional Runecloth, 20 Runecloth at a time. Runecloth: Dark Adepts and Shadowmages (level 58-60) in Eastern Plaguelands, or the Auction House.", title = "Additional Runecloth to Revered"},
	{{"have", 14047, 20, at = {1423, 34.34, 42.41}, name = "Runecloth", optional = true}, {"turnin", 7837, at = {1454, 37.7, 87.9}, optional = true, who = "Vehena"}, {"note", "Darkspear Trolls: reach Exalted"}, note = "Keep handing in Additional Runecloth until Darkspear Trolls is Exalted. Runecloth: Dark Adepts and Shadowmages (level 58-60) in Eastern Plaguelands, or the Auction House.", title = "Additional Runecloth to Exalted"},
} })

