Pathwise.RegisterRoute({category = "Reputation", id = "forever/reputation/hydraxian-waterlords", levels = {60, 60}, map = 1447, title = "Hydraxian Waterlords Reputation", steps = {
	{{"accept", 6804, at = {1447, 79.28, 73.7}, who = "Duke Hydraxis"}, {"accept", 6805, at = {1447, 79.28, 73.7}, who = "Duke Hydraxis"}, note = "Duke Hydraxis stands on a small island off the eastern coast of Azshara; swim or walk the shallows out to him. The Hydraxian Waterlords start out Neutral. Forever's Legacy Diplomat perk increases reputation gains.", title = "Duke Hydraxis"},
	{{"complete", 6805, at = {1451, 19.6, 26.4}}, note = "Both elementals roam north-western Silithus; the Rumblers cluster a little further north.", title = "Dust Stormers and Desert Rumblers"},
	{{"complete", 6804, at = {1423, 54.02, 68.69}}, note = "Use the Aspect of Neptulon on the poisoned water elementals of Eastern Plaguelands, then loot their Discordant Bracers (12).", title = "Poisoned Water"},
	{{"turnin", 6804, at = {1447, 79.28, 73.7}, who = "Duke Hydraxis"}, {"turnin", 6805, at = {1447, 79.28, 73.7}, who = "Duke Hydraxis"}, {"accept", 6821, at = {1447, 79.28, 73.7}, who = "Duke Hydraxis"}, title = "Back to Duke Hydraxis"},
	{{"complete", 6821}, {"turnin", 6821, at = {1447, 79.28, 73.7}, who = "Duke Hydraxis"}, {"accept", 6822, at = {1447, 79.28, 73.7}, who = "Duke Hydraxis"}, note = "Pyroguard Emberseer in Upper Blackrock Spire drops the Eye of the Emberseer. This needs a raid group.", title = "Eye of the Emberseer"},
	{{"complete", 6822}, {"turnin", 6822, at = {1447, 79.28, 73.7}, who = "Duke Hydraxis"}, {"note", "Hydraxian Waterlords: reach Friendly"}, note = "Kill a Firelord, a Molten Giant, an Ancient Core Hound and a Lava Surger in the Molten Core. Every Molten Core elemental and boss also counts toward the Waterlords.", title = "The Molten Core"},
	{{"accept", 6823, at = {1447, 79.28, 73.7}, who = "Duke Hydraxis"}, {"note", "Hydraxian Waterlords: reach Honored"}, {"turnin", 6823, at = {1447, 79.28, 73.7}, who = "Duke Hydraxis"}, {"accept", 6824, at = {1447, 79.28, 73.7}, who = "Duke Hydraxis"}, note = "Agent of Hydraxis needs Honored. At Honored, Duke Hydraxis hands out Aqual Quintessence, used to douse the runes in the Molten Core that summon Majordomo Executus; at Revered, the reusable Eternal Quintessence.", title = "Agent of Hydraxis"},
	{{"complete", 6824}, {"turnin", 6824, at = {1447, 79.28, 73.7}, who = "Duke Hydraxis"}, note = "Bring the Hands of Lucifron, Gehennas, Shazzrah and Sulfuron from the Molten Core.", title = "Hands of the Enemy"},
	{{"note", "Hydraxian Waterlords: reach Revered"}, note = "Molten Core clears carry the rest. Bosses always count; in Classic, trash kills stop giving Waterlords reputation partway up, so late on the bosses do the work.", title = "Hydraxian Waterlords to Revered"},
	{{"note", "Hydraxian Waterlords: reach Exalted"}, note = "Keep clearing the Molten Core until Exalted.", title = "Hydraxian Waterlords to Exalted"},
} })

