Pathwise.RegisterRoute({category = "Reputation", id = "forever/reputation/merchants-favor", levels = {10, 60}, map = 1433, title = "Merchant's Favor Reputation", steps = {
	{{"goto", 1433, 9.8, 71, "Marcy Baker"}, {"note", "Azeroth Commerce Authority: reach Friendly"}, note = "The Azeroth Commerce Authority is the Alliance's tradeskill faction in Forever. Its camp is at Three Corners in western Redridge Mountains. From level 10 mobs drop Waylaid Crates: fill each with the goods its label asks for and hand the Sealed Crate to Marcy Baker at the camp for reputation and Merchant's Favor. Forever's Legacy Diplomat perk increases reputation gains.", only = {factions = {"Alliance"}}, title = "Azeroth Commerce Authority to Friendly"},
	{{"note", "Azeroth Commerce Authority: reach Honored"}, note = "Keep filling Waylaid Crates for Marcy Baker.", only = {factions = {"Alliance"}}, title = "Azeroth Commerce Authority to Honored"},
