Pathwise.RegisterRoute({category = "Reputation", id = "forever/reputation/thorium-brotherhood", levels = {48, 60}, map = 1427, title = "Thorium Brotherhood Reputation", steps = {
	{{"accept", 7722, at = {1427, 38.8, 28.51}, who = "Master Smith Burninate"}, note = "Thorium Point, on the scaffolds in the north-west of Searing Gorge, is the Brotherhood's outpost. The Thorium Brotherhood starts out Neutral. Forever's Legacy Diplomat perk increases reputation gains.", title = "Master Smith Burninate"},
	{{"complete", 7722, at = {1427, 40.4, 35.7}}, note = "The plans lie in the Slag Pit of the Cauldron, guarded by Dark Iron dwarves. Dark Iron dwarves also drop Dark Iron Residue, which Burninate takes for Gaining Acceptance.", title = "Secret Plans: Fiery Flux"},
	{{"turnin", 7722, at = {1427, 38.8, 28.51}, who = "Master Smith Burninate"}, title = "Back to Burninate"},
	{{"have", 18944, 1, at = {1427, 44.6, 24.9}, name = "Incendosaur Scale", optional = true}, {"goto", 1427, 38.8, 28.51, "Talk to Master Smith Burninate", optional = true}, {"note", "Thorium Brotherhood: reach Friendly"}, note = "Restoring Fiery Flux Supplies repeats in three versions: Kingsblood, Iron Bars or Heavy Leather, each with Coal and an Incendosaur Scale. Incendosaurs (level 47-49) in the north of Searing Gorge drop a scale every time; Burninate himself sells Coal.", title = "Fiery Flux supplies to Friendly"},
	{{"goto", 1427, 32.1, 94.7, "Blackrock Mountain"}, {"note", "Dark Iron Ore: Favor Amongst the Brotherhood, Dark Iron Ore at Lokhtos, repeatable."}, {"note", "Thorium Brotherhood: reach Honored"}, note = "Lokhtos Darkbargainer trades in the Grim Guzzler inside Blackrock Depths. His Favor Amongst the Brotherhood turn-ins take Dark Iron Ore (mined from Dark Iron Deposits with Mining), Blood of the Mountain, Fiery Core, Lava Core and Core Leather. Lothos Riftwaker at the Blackrock Mountain entrance offers attunement to the Molten Core.", title = "Lokhtos Darkbargainer to Honored"},
	{{"note", "Molten Core materials: Favor Amongst the Brotherhood, Fiery Core, Lava Core, Core Leather and Blood of the Mountain, all repeatable at Lokhtos."}, {"note", "Thorium Brotherhood: reach Revered"}, note = "The Molten Core materials carry the rest: Fiery Cores drop from Firewalkers, Flameguards and Firelords, and Lava Cores from Lava Elementals, Lava Reavers and Molten Destroyers there. Blood of the Mountain comes from Molten Destroyers and rarely elsewhere.", title = "Thorium Brotherhood to Revered"},
	{{"note", "Thorium Brotherhood: reach Exalted"}, note = "Keep turning in Molten Core materials and Dark Iron Ore at Lokhtos until Exalted.", title = "Thorium Brotherhood to Exalted"},
} })

