Pathwise.RegisterRoute({category = "Reputation", id = "forever/reputation/timbermaw-hold", levels = {48, 60}, map = 1448, title = "Timbermaw Hold Reputation", steps = {
	{{"accept", 8460, at = {1448, 50.9, 85}, who = "Grazle"}, note = "Timbermaw Hold starts out Hostile, and its furbolgs in the tunnels attack until you reach Unfriendly. Every Deadwood and Winterfall furbolg you kill raises it, so the quests below pay twice. Forever's Legacy Diplomat perk increases reputation gains.", title = "Grazle"},
	{{"complete", 8460, at = {1448, 48.2, 91.2}}, note = "Deadwood furbolgs (level 48-50) camp at the southern end of Felwood. Keep every Deadwood Headdress Feather they drop: Grazle and Nafien take them later.", title = "Deadwood Village"},
	{{"turnin", 8460, at = {1448, 50.9, 85}, who = "Grazle"}, {"accept", 8462, at = {1448, 50.9, 85}, who = "Grazle"}, title = "Back to Grazle"},
	{{"turnin", 8462, at = {1448, 64.8, 8.1}, who = "Nafien"}, {"accept", 8461, at = {1448, 64.8, 8.1}, who = "Nafien"}, note = "Nafien waits in northern Felwood at the tunnel into Timbermaw Hold.", title = "Nafien"},
	{{"complete", 8461, at = {1448, 62.2, 9}}, note = "The northern Deadwood (level 53-55) hold the camps just south of the tunnel. Keep their feathers too.", title = "Deadwood of the North"},
	{{"turnin", 8461, at = {1448, 64.8, 8.1}, who = "Nafien"}, {"accept", 8465, at = {1448, 64.8, 8.1}, who = "Nafien"}, title = "Back to Nafien"},
	{{"turnin", 8465, at = {1452, 27.7, 34.5}, who = "Salfa"}, {"accept", 8464, at = {1452, 27.7, 34.5}, who = "Salfa"}, note = "Go through Timbermaw Hold to its Winterspring exit; Salfa stands just outside. The quests and kills so far usually reach Unfriendly, and then the Timbermaw let you pass. If they still show red, kill more Deadwood by the tunnel first.", title = "Salfa"},
	{{"complete", 8464, at = {1452, 67.37, 35.22}}, note = "Winterfall Village sits on the eastern side of Winterspring. Keep every Winterfall Spirit Beads you loot: Salfa takes them.", title = "Winterfall Village"},
	{{"turnin", 8464, at = {1452, 27.7, 34.5}, who = "Salfa"}, title = "Back to Salfa"},
	{{"have", 21383, 5, at = {1452, 67.1, 37.6}, name = "Winterfall Spirit Beads", optional = true}, {"goto", 1452, 27.73, 34.5, "Talk to Salfa", optional = true}, {"note", "Timbermaw Hold: reach Friendly"}, note = "Feathers for Grazle and Feathers for Nafien (Deadwood Headdress Feathers) and Beads for Salfa (Winterfall Spirit Beads) repeat as often as you like; every Deadwood or Winterfall kill counts as well. Winterfall Village is the densest bead spot.", title = "Feathers and beads to Friendly"},
	{{"have", 21377, 5, at = {1448, 62.2, 9}, name = "Deadwood Headdress Feather", optional = true}, {"goto", 1448, 64.77, 8.13, "Talk to Nafien", optional = true}, {"note", "Timbermaw Hold: reach Honored"}, note = "The northern Deadwood camps by the tunnel are the densest feather spot (35% drop chance there). Hand feathers to Nafien at the tunnel, or to Grazle in the south.", title = "Feathers to Honored"},
	{{"have", 21377, 5, at = {1448, 62.2, 9}, name = "Deadwood Headdress Feather", optional = true}, {"goto", 1448, 64.77, 8.13, "Talk to Nafien", optional = true}, {"note", "Timbermaw Hold: reach Revered"}, note = "Alternate Deadwood feathers (Nafien) and Winterfall beads (Salfa), whichever camp is less crowded.", title = "Timbermaw Hold to Revered"},
	{{"have", 21377, 5, at = {1448, 62.2, 9}, name = "Deadwood Headdress Feather", optional = true}, {"goto", 1448, 64.77, 8.13, "Talk to Nafien", optional = true}, {"note", "Timbermaw Hold: reach Exalted"}, note = "Keep turning in feathers and beads until Exalted.", title = "Timbermaw Hold to Exalted"},
} })

