Pathwise.RegisterRoute({category = "Reputation", id = "forever/reputation/warsong-gulch", levels = {10, 60}, map = 1440, title = "Warsong Gulch Reputation", steps = {
	{{"goto", 1440, 61.85, 83.9, "Talk to Sentinel Farsong", optional = true}, {"note", "Sentinel Farsong takes Warsong Gulch Marks of Honor for Vanquish the Invaders!, once per level bracket (data); check them live."}, {"note", "Silverwing Sentinels: reach Friendly"}, note = "The Silverwing Sentinels are the Night Elves holding Warsong Gulch. Their reputation comes from the battleground: every enemy flag your team captures pays it to the whole team. Queue at any battlemaster. Forever's Legacy Diplomat perk increases reputation gains.", only = {factions = {"Alliance"}}, title = "Silverwing Sentinels to Friendly"},
	{{"goto", 1440, 61.49, 83.86, "Talk to Illiyana Moonblaze", optional = true}, {"note", "Silverwing Sentinels: reach Honored"}, note = "Keep playing Warsong Gulch and capturing flags. On Call to Arms: Warsong Gulch weekends the Alliance Brigadier General in the capitals takes three Warsong Gulch Marks of Honor for extra reputation.", only = {factions = {"Alliance"}}, title = "Silverwing Sentinels to Honored"},
